SELECT PSP.PORTFOLIO_ID as portfolioId,/* 组合持仓.组合代码*/ PSP.FINPROD_ID as finprodId, /* 组合持仓.金融产品代码*/ FP.FINPROD_TYPE2 as finprodType2, /* 标的类金融产品.金融产品类型（投管）*/ FP.CCY as ccy, /*标的类金融产品.币种 */ FP.TRADE_MARKET as tradeMarket, /*标的类金融产品.交易场所*/ PSP.AMOUNT as redDateAmt, /*组合持仓.数量 */ MFBN.REG_DATE as regDate, /*基金分红公告.权益登记日*/ MFBN.DEL_DATE as delDate, /*基金分红公告.除权日*/ MFBN.DEVIDENT_DATE as devidentDate, /*基金分红公告.派息日*/ MFBN.UNIT_BONUS_UNIT_VALUE as unitBonusUnitValue, /*基金分红公告.单位分红净值*/ (MFBN.UNIT_BONUS_UNIT_VALUE * PSP.AMOUNT) as bonusAmt, /*分红金额 基金分红公告.单位分红净值*组合持仓.数量*/ (SELECT BONUS_MODE FROM( SELECT * FROM PORTFOLIO_FUND_BONUS_MODE PFBM ORDER BY PFBM.SET_DATE DESC) a WHERE a.FINPROD_ID = concat('F06_', MFBN.FUND_ID) AND a.PORTFOLIO_ID = PSP.PORTFOLIO_ID AND a.SET_DATE <= MFBN.REG_DATE AND rownum = 1) AS bonusMode,/*组合基金分红方式.分红方式 */ PSP.SEC_ACCT_ID as secAcctId /*组合持仓.证券账户代码*/ FROM PTL_SEC_POSITION PSP /*组合持仓*/ LEFT JOIN FIN_PRODUCT FP /*标的类金融产品*/ ON FP.FINPROD_ID = PSP.FINPROD_ID AND FP.FINPROD_TYPE2 = 'F06' AND FP.FINPROD_TYPE = 'F06' INNER JOIN MST_FUND_BONUS_NOTICE MFBN /*基金分红公告*/ ON MFBN.FUND_ID = FP.FINPROD_MARKET_ID AND MFBN.REG_DATE = PSP.CDATE LEFT JOIN PORTFOLIO_FUND_BONUS_MODE PFBM ON PFBM.FINPROD_ID = MFBN.FUND_ID AND PFBM.PORTFOLIO_ID = PSP.PORTFOLIO_ID AND PFBM.SET_DATE <= MFBN.REG_DATE
LEFT JOIN fin_product_type fpt ON PSP.FINPROD_ID=fpt.FINPROD_ID
PSP.HODING_TYPE = '03'
AND fpt.TYPE_10 != '24'
AND MFBN.REG_DATE = #{dealDate,jdbcType=DATE}
#{portfolioId,jdbcType=VARCHAR}

SELECT PSP.PORTFOLIO_ID as portfolioId,/* 组合持仓.组合代码*/ PSP.FINPROD_ID as finprodId, /* 组合持仓.金融产品代码*/ FP.FINPROD_TYPE2 as finprodType2, /* 标的类金融产品.金融产品类型（投管）*/ FP.CCY as ccy, /*标的类金融产品.币种 */ FP.TRADE_MARKET as tradeMarket, /*标的类金融产品.交易场所*/ PSP.AMOUNT as redDateAmt, /*组合持仓.数量 */ MFBN.REG_DATE as regDate, /*基金分红公告.权益登记日*/ MFBN.DEL_DATE as delDate, /*基金分红公告.除权日*/ MFBN.DEVIDENT_DATE as devidentDate, /*基金分红公告.派息日*/ MFBN.UNIT_BONUS_UNIT_VALUE as unitBonusUnitValue, /*基金分红公告.单位分红净值*/ (MFBN.UNIT_BONUS_UNIT_VALUE * PSP.AMOUNT) as bonusAmt, /*分红金额 基金分红公告.单位分红净值*组合持仓.数量*/ ( SELECT BONUS_MODE FROM (SELECT * FROM PORTFOLIO_FUND_BONUS_MODE PFBM ORDER BY PFBM.SET_DATE DESC) a WHERE a.FINPROD_ID = concat('F06_', MFBN.FUND_ID) AND a.PORTFOLIO_ID = PSP.PORTFOLIO_ID AND a.SET_DATE<= MFBN.REG_DATE AND rownum = 1) AS bonusMode,/*组合基金分红方式.分红方式 */ PSP.SEC_ACCT_ID as secAcctId /*组合持仓.证券账户代码*/ FROM PTL_SEC_POSITION_RULE PSP /*组合持仓*/ LEFT JOIN FIN_PRODUCT FP /*标的类金融产品*/ ON FP.FINPROD_ID = PSP.FINPROD_ID AND FP.FINPROD_TYPE2 = 'F06' AND FP.FINPROD_TYPE = 'F06' INNER JOIN MST_FUND_BONUS_NOTICE MFBN /*基金分红公告*/ ON MFBN.FUND_ID = FP.FINPROD_MARKET_ID AND MFBN.REG_DATE = PSP.CDATE LEFT JOIN PORTFOLIO_FUND_BONUS_MODE PFBM ON PFBM.FINPROD_ID = MFBN.FUND_ID AND PFBM.PORTFOLIO_ID = PSP.PORTFOLIO_ID AND PFBM.SET_DATE <= MFBN.REG_DATE
LEFT JOIN fin_product_type fpt ON PSP.FINPROD_ID=fpt.FINPROD_ID
PSP.HODING_TYPE = #{hodingType,jdbcType=VARCHAR} AND PSP.DATE_TYPE = #{dateType,jdbcType=NUMERIC}
AND fpt.TYPE_10 != '24'
AND MFBN.REG_DATE = #{dealDate,jdbcType=DATE}
#{portfolioId,jdbcType=VARCHAR}

SELECT fp.FINPROD_ID finprodId,
fp.FINPROD_TYPE2, fp.CCY,
fp.TRADE_MARKET tradeMarket, sbr.SHARES_ID , sbr.REG_DATE regDate, sbr.DEL_DATE delDate, sbr.DEVIDENT_DATE devidentDate, sbr.PER_DEVIDENT_AMT preDevidengAmt, psp.PORTFOLIO_ID portfolioId, psp.AMOUNT redDateAmt, psp.SEC_ACCT_ID secAcctId, sbr.PER_DEVIDENT_AMT * psp.AMOUNT as bonusAmt FROM SHARE_BONUS_REG sbr LEFT JOIN fin_product fp ON fp.FINPROD_MARKET_ID = sbr.SHARES_ID AND fp.FINPROD_TYPE = 'F10' AND fp.FINPROD_TYPE2 = 'F10' INNER JOIN ptl_sec_position psp ON fp.FINPROD_ID = psp.FINPROD_ID AND psp.CDATE = REG_DATE AND psp.HODING_TYPE = '03'
sbr.REG_DATE = #{dealDate,jdbcType=DATE}
#{portfolioId,jdbcType=VARCHAR}

SELECT std.TRADE_ID, std.DEAL_DATE , std.FINPROD_ID , std.BUSI_TYPE , std.PS , std.TRADE_MARKET , std.FINPROD_TYPE , std.FINPROD_TYPE2 , std.TRADE_DATE , std.SETTLE_DATE , std.SEC_ACCT_ID , std.ACCT_NO , std.CCY , std.UNIT_CPRICE , std.UNIT_INT , std.PRIN_AMT , std.INT_AMT , std.FPRICE_AMT , std.TRADE_AMT , std.SHARE_AMT , psp.PORTFOLIO_ID, psp.AMOUNT , psp.CDATE regDate FROM SETTLE_TRANS_DATA std
INNER JOIN ptl_sec_position psp
ON psp.FINPROD_ID = std.FINPROD_ID AND psp.SEC_ACCT_ID = std.SEC_ACCT_ID AND psp.CDATE = std.TRADE_DATE AND psp.HODING_TYPE = #{HODING_TYPE_03}
std.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} AND std.DELIVERY_RESULT IN (#{DELIVERY_RESULT_01}, #{DELIVERY_RESULT_02}) AND std.DEAL_DATE = #{dealDate,jdbcType=DATE} AND (std.TRADE_MARKET = #{TRADE_MARKET_04} or (std.TRADE_MARKET = #{TRADE_MARKET_03} and std.PS = #{PS_T11}))
#{portfolioId,jdbcType=VARCHAR}
#{ps,jdbcType=VARCHAR}
UNION ALL
SELECT std.TRADE_ID, std.DEAL_DATE , std.FINPROD_ID , std.BUSI_TYPE , std.PS , std.TRADE_MARKET , std.FINPROD_TYPE , std.FINPROD_TYPE2 , std.TRADE_DATE , std.SETTLE_DATE , std.SEC_ACCT_ID , std.ACCT_NO , std.CCY , std.UNIT_CPRICE , std.UNIT_INT , std.PRIN_AMT , std.INT_AMT , std.FPRICE_AMT , std.TRADE_AMT , std.SHARE_AMT , psp.PORTFOLIO_ID, psp.AMOUNT , psp.CDATE regDate FROM SETTLE_TRANS_DATA std INNER JOIN SHARE_BONUS_REG sbr ON concat('F10_', sbr.SHARES_ID) = std.FINPROD_ID AND sbr.SEC_ACCT_ID = std.SEC_ACCT_ID
INNER JOIN ptl_sec_position psp
ON psp.FINPROD_ID = std.FINPROD_ID AND psp.SEC_ACCT_ID = std.SEC_ACCT_ID AND psp.CDATE = sbr.REG_DATE AND psp.HODING_TYPE = #{HODING_TYPE_03}
std.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} AND std.DELIVERY_RESULT IN (#{DELIVERY_RESULT_01}, #{DELIVERY_RESULT_02}) AND std.DEAL_DATE = #{dealDate,jdbcType=DATE} AND std.TRADE_MARKET = #{TRADE_MARKET_03} AND std.PS = #{PS_T12}
#{portfolioId,jdbcType=VARCHAR}
#{ps,jdbcType=VARCHAR}

SELECT std.TRADE_ID, std.DEAL_DATE , std.FINPROD_ID , std.BUSI_TYPE , std.PS , std.TRADE_MARKET , std.FINPROD_TYPE , std.FINPROD_TYPE2 , std.TRADE_DATE , std.SETTLE_DATE , std.SEC_ACCT_ID , std.ACCT_NO , std.CCY , std.UNIT_CPRICE , std.UNIT_INT , std.PRIN_AMT , std.INT_AMT , std.FPRICE_AMT , std.TRADE_AMT , std.SHARE_AMT , psp.PORTFOLIO_ID, psp.AMOUNT , psp.CDATE regDate FROM SETTLE_TRANS_DATA std INNER JOIN PTL_SEC_POSITION_RULE psp ON psp.FINPROD_ID = std.FINPROD_ID AND psp.SEC_ACCT_ID = std.SEC_ACCT_ID AND psp.CDATE = std.TRADE_DATE AND PSP.HODING_TYPE = #{hodingType,jdbcType=VARCHAR} AND PSP.DATE_TYPE = #{dateType,jdbcType=NUMERIC}
std.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} AND std.DELIVERY_RESULT IN (#{DELIVERY_RESULT_01}, #{DELIVERY_RESULT_02}) AND std.DEAL_DATE = #{dealDate,jdbcType=DATE} AND (std.TRADE_MARKET = #{TRADE_MARKET_04} or (std.TRADE_MARKET = #{TRADE_MARKET_03} and std.PS = #{PS_T11}))
#{portfolioId,jdbcType=VARCHAR}
#{ps,jdbcType=VARCHAR}
UNION ALL
SELECT std.TRADE_ID, std.DEAL_DATE , std.FINPROD_ID , std.BUSI_TYPE , std.PS , std.TRADE_MARKET , std.FINPROD_TYPE , std.FINPROD_TYPE2 , std.TRADE_DATE , std.SETTLE_DATE , std.SEC_ACCT_ID , std.ACCT_NO , std.CCY , std.UNIT_CPRICE , std.UNIT_INT , std.PRIN_AMT , std.INT_AMT , std.FPRICE_AMT , std.TRADE_AMT , std.SHARE_AMT , psp.PORTFOLIO_ID, psp.AMOUNT , psp.CDATE regDate FROM SETTLE_TRANS_DATA std INNER JOIN SHARE_BONUS_REG sbr ON concat('F10_', sbr.SHARES_ID) = std.FINPROD_ID AND sbr.SEC_ACCT_ID = std.SEC_ACCT_ID INNER JOIN PTL_SEC_POSITION_RULE psp ON psp.FINPROD_ID = std.FINPROD_ID AND psp.SEC_ACCT_ID = std.SEC_ACCT_ID AND psp.CDATE = sbr.REG_DATE AND PSP.HODING_TYPE = #{hodingType,jdbcType=VARCHAR} AND PSP.DATE_TYPE = #{dateType,jdbcType=NUMERIC}
std.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} AND std.DELIVERY_RESULT IN (#{DELIVERY_RESULT_01}, #{DELIVERY_RESULT_02}) AND std.DEAL_DATE = #{dealDate,jdbcType=DATE} AND std.TRADE_MARKET = #{TRADE_MARKET_03} AND std.PS = #{PS_T12}
#{portfolioId,jdbcType=VARCHAR}
#{ps,jdbcType=VARCHAR}

SELECT std.FINPROD_ID , std.PS , std.TRADE_MARKET , std.FINPROD_TYPE , std.FINPROD_TYPE2 , std.TRADE_DATE , std.SETTLE_DATE , std.SEC_ACCT_ID , std.ACCT_NO , std.CCY , std.UNIT_CPRICE , std.UNIT_INT , std.UNIT_FPRICE, std.PAR_VALUE , std.CPRICE_AMT, std.SHARE_AMT , std.PRIN_AMT , std.INT_AMT , std.FPRICE_AMT , std.TRADE_AMT , std.TRADE_ID, tpd.SHARE_AMT shareAmtSg, tpda.PORTFOLIO_ID, tpd.INV_AIM, tpda.ENTRUST_ID orderId, tpd.TRADE_ID bTradeId FROM SETTLE_TRANS_DATA std INNER JOIN TRD_PRODUCT_DEAL tpd ON std.FINPROD_ID = tpd.FINPROD_ID AND tpd.PS = #{PS_T04} AND tpd.TRADE_DATE < std.DEAL_DATE AND tpd.SEAT_ID = std.SEAT_NUMBER AND tpd.SEC_MANAGE_ACCT_ID = std.SEC_ACCT_ID AND tpd.IS_CANCEL = #{IS_CANCEL_N} AND tpd.TRADE_STATUS = #{TRADE_STATUS_01} LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID
std.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} AND std.DEAL_DATE = #{dealDate,jdbcType=DATE} AND std.PS = #{PS_T05} AND std.DELIVERY_RESULT IN (#{DELIVERY_RESULT_01}, #{DELIVERY_RESULT_02})
#{portfolioId,jdbcType=VARCHAR}

SELECT
A.TOTLE_TRADE_ID
FROM
TRD_FIN_PRODUCT_DEAL_TOTAL A,
PA_TRD_FIN_PRODUCT_DEAL_TOTAL B

	A.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND A.PS = #{ps,jdbcType=VARCHAR} AND A.TRADE_DATE <= #{fhDate,jdbcType=DATE}
	AND A.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} AND A.IS_CANCEL = #{isCancel,jdbcType=VARCHAR}
	AND A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID AND B.BONUS_CFM_DATE = #{fhDate,jdbcType=DATE}

SELECT SEC_ACCT_ID, FINPROD_ID, PORTFOLIO_ID, SUM(AMOUNT) AMOUNT FROM PTL_SEC_POSITION_RULE WHERE 1=1
AND HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
AND CDATE = #{dealDate,jdbcType=DATE}
AND DATE_TYPE = #{dateType,jdbcType=NUMERIC}
GROUP BY SEC_ACCT_ID, FINPROD_ID, PORTFOLIO_ID

SELECT trd.TRADE_ID tradeId2, trd.TOTLE_TRADE_ID tradeTotalId, trda.PURCH_MODLE purchModle, trda.PURCH_TYPE purchType, trd.TRADE_DATE purchDate, trd.COUNTER_ID purchCounter, trd.PRIN_AMT purchAmt, trda.PORTFOLIO_ID PORTFOLIO_ID, trd.SHARE_AMT SHARE_NUM, trda.ENTRUST_ID ENTRUST_ID, trd.INV_AIM INV_AIM,
LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = std.FINPROD_ID INNER JOIN TRD_PRODUCT_DEAL trd ON trd.PS = #{PS_T04}
AND trd.FINPROD_ID = std.FINPROD_ID
AND trd.TRADE_DATE < std.DEAL_DATE AND trd.SEAT_ID = std.SEAT_NUMBER AND trd.SEC_MANAGE_ACCT_ID = std.SEC_ACCT_ID AND trd.IS_CANCEL = #{IS_CANCEL_N} AND trd.TRADE_STATUS = #{TRADE_STATUS_01} LEFT JOIN TRD_PRODUCT_DEAL_ADD trda ON trda.TRADE_ID = trd.TRADE_ID
std.PS = #{PS_T05} AND std.DELIVERY_RESULT IN (#{DELIVERY_RESULT_01}, #{DELIVERY_RESULT_02})
AND std.DEAL_DATE = #{dealDate,jdbcType=DATE}
#{finprodId,jdbcType=VARCHAR}
#{finprodType,jdbcType=VARCHAR}
#{portfolioId,jdbcType=VARCHAR}

SELECT SEC_ACCT_ID secAcctId, FINPROD_ID finprodId, max(CDATE) dealDate FROM FIN_PRODUCT_QUTO WHERE 1=1
AND FIN_PRODUCT_QUTO.CDATE = #{dealDate,jdbcType=DATE}
AND FIN_PRODUCT_QUTO.OTH_TYPE = #{OTH_TYPE_15} GROUP BY SEC_ACCT_ID, FINPROD_ID

SELECT PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, CCY, AMOUNT, TRADE_ID, ENTRUST_ID FROM PTL_SEC_POSITION_FLOW_RULE WHERE 1=1
AND HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
AND CDATE <= #{dealDate,jdbcType=DATE}
AND DATE_TYPE = #{dateType,jdbcType=NUMERIC}

SELECT std.SEQ_NO TRADE_ID, /*std.CJBH CJBH,*/ std.DEAL_DATE DEAL_DATE,/*执行日期*/ std.FINPROD_ID,/*金融产品代码*/ std.PS,/*交易方向*/ std.TRADE_MARKET,/*交易场所*/ std.FINPROD_TYPE,/*金融产品类型（估值核算）*/ std.FINPROD_TYPE2,/*金融产品类型（投管分类）*/ std.TRADE_DATE,/*交易日期*/ std.SETTLE_DATE,/*交割日期*/ std.SEC_ACCT_ID,/*证券账户*/ std.ACCT_NO,/*资金账户*/ std.CCY,/*交易币种*/ std.UNIT_CPRICE,/*单位净价*/ std.PRIN_AMT,/*交易本金*/ std.INT_AMT,/*利息总额*/ std.FPRICE_AMT,/*全价总额*/ std.FRAGMENTARY_FUNDS,/*零碎份额资金*/ std.TRADE_AMT,/*交易金额*/ std.BUSI_TYPE,/*业务类型*/ decode(fpt.TYPE_10,'24','Y','N') isHuobi/*是否货币基金*/ FROM SETTLE_TRANS_DATA std LEFT JOIN fin_product_type fpt ON std.FINPROD_ID=fpt.FINPROD_ID
std.DEAL_DATE = #{dealDate,jdbcType=DATE} AND std.DELIVERY_RESULT IN (#{DELIVERY_RESULT_01}, #{DELIVERY_RESULT_02}) AND std.FINPROD_TYPE2 = 'F06'
#{ps,jdbcType=VARCHAR}

select t1.TOTLE_TRADE_ID
from TRD_FIN_PRODUCT_DEAL_TOTAL t1
where t1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and t1.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}
  and t1.PS = 'T13'
  and t1.REG_DATE = #{dealDate,jdbcType=DATE}
  and t1.SEC_MANAGE_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}

select t1.TRADE_ID
from TRD_PRODUCT_DEAL t1
where t1.TOTLE_TRADE_ID = #{id}

