SELECT T1.VDATE, T1.MDATE, T1.FINPROD_ID FROM FIN_EXERCISE_PLAN T1
T1.EXERCISE_TYPE = '02'
AND T1.FINPROD_ID IN
#{currData.finprodId,jdbcType=VARCHAR}
AND T1.MDATE <= #{dealDate,jdbcType=DATE}
order by T1.FINPROD_ID, T1.VDATE desc

SELECT T1.FINPROD_ID, T1.OTH_TYPE, T1.DECLARED_START_DATE, T1.DECLARED_END_DATE from FIN_PRODUCT_OTH_CODE T1
T1.OTH_TYPE in ('05', '06')
AND T1.FINPROD_ID IN
#{currData.finprodId,jdbcType=VARCHAR}
AND CASE WHEN T1.OTH_TYPE = '05' THEN T1.DECLARED_START_DATE WHEN T1.OTH_TYPE = '06' THEN T1.DECLARED_END_DATE END <= #{dealDate,jdbcType=DATE}
order by T1.FINPROD_ID, T1.DECLARED_START_DATE desc

SELECT
DISTINCT  sttm.TRADE_ID_TG
FROM SETTLE_TRANS_TG_MAPPING sttm
WHERE sttm.TRADE_ID in(
	SELECT std.SEQ_NO
	FROM SETTLE_TRANS_DATA std
	WHERE std.APPLY_TRADE_ID = #{applyTradeId, jdbcType=VARCHAR}
	AND  std.DEAL_DATE = #{dealDate,jdbcType=DATE}
	AND std.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
	AND std.SEAT_NUMBER = #{seatNumber, jdbcType=VARCHAR}
)

SELECT std.*
FROM SETTLE_TRANS_DATA std
WHERE std.APPLY_TRADE_ID = #{applyTradeId, jdbcType=VARCHAR}
AND  std.DEAL_DATE = #{dealDate,jdbcType=DATE}
AND std.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND std.SEAT_NUMBER = #{seatNumber, jdbcType=VARCHAR}

SELECT FINPROD_ABBR
FROM TRD_BANK_MANUAL_SETTLE_FLOW
WHERE FINPROD_ID = #{finprodId, jdbcType=VARCHAR}

